// Acceptance tests for L1 (the core). Written by the main thread BEFORE the batch.
// Workers do not edit this file. Contract: docs/arquitectura/03-contratos.md §4.5-4.11.
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { copyFixture, sha256, sleep, snapshot } from '../helpers/fixture.mjs';
import { grantLease } from '../../src/leases.js';
import { readLedger } from '../../src/ledger.js';
import { listNotes, openRoot } from '../../src/root.js';
import {
  asOf,
  commitWrite,
  editNote,
  history,
  initRoot,
  moveNote,
  prepareWrite,
  readNote,
  restore,
  showVersion,
  writeNote,
} from '../../src/store.js';

/** @typedef {import('../../src/types.js').Author} Author */

/** @type {Author} */ const A = { session: 'session-a', agent: 'cli' };
/** @type {Author} */ const B = { session: 'session-b', agent: 'cli' };
/** @type {Author} */ const ADOPTER = { session: 'adopter', agent: 'adopt' };
const WRITER = fileURLToPath(new URL('./writer.mjs', import.meta.url));
const GAMMA = 'projects/gamma.md';
const WITH_A = "# Gamma\n\n## A's part\n\nwritten by A\n";

async function adopted() {
  const dir = copyFixture();
  await initRoot(dir, { adopt: true, author: ADOPTER });
  return openRoot(dir);
}

/** @param {import('../../src/types.js').Root} root */
const lastEntry = (root) => readLedger(root).entries.at(-1);

test('adopting a folder governs every note and modifies none', async () => {
  const dir = copyFixture();
  const before = snapshot(dir);
  const result = await initRoot(dir, { adopt: true, author: ADOPTER });
  assert.deepEqual(snapshot(dir), before, 'no note may change on adopt');
  const root = openRoot(dir);
  const notes = listNotes(root);
  assert.equal(result.notes, notes.length);
  const { entries, corrupt } = readLedger(root);
  assert.equal(corrupt, 0);
  assert.equal(entries.filter((e) => e.op === 'adopt').length, notes.length);
  assert.ok(entries.every((e) => Object.keys(e.delta).length === 0), 'nobody owns adopted headings');
});

test('init refuses a folder with notes unless adopting, and refuses a root twice', async () => {
  const dir = copyFixture();
  await assert.rejects(initRoot(dir, { adopt: false, author: ADOPTER }), { code: 'ROOT_HAS_NOTES' });
  await initRoot(dir, { adopt: true, author: ADOPTER });
  await assert.rejects(initRoot(dir, { adopt: true, author: ADOPTER }), { code: 'ROOT_EXISTS' });
});

test('a write records author, reason and both versions', async () => {
  const root = await adopted();
  const res = await writeNote(root, GAMMA, WITH_A, { author: A, reason: 'create gamma' });
  assert.equal(res.ok, true);
  if (!res.ok) return;
  assert.equal(res.entry.op, 'write');
  assert.equal(res.entry.author.session, 'session-a');
  assert.equal(res.entry.reason, 'create gamma');
  assert.equal(res.entry.before, null);
  assert.equal(res.entry.after, sha256(WITH_A));
  assert.equal(showVersion(root, sha256(WITH_A)), WITH_A);
  assert.equal(res.entry.delta["## A's part"], 1);
  assert.deepEqual(lastEntry(root), res.entry);
});

test('the guard blocks removing a section written by another session, and leaves the file alone', async () => {
  const root = await adopted();
  await writeNote(root, GAMMA, WITH_A, { author: A, reason: 'create' });
  const res = await writeNote(root, GAMMA, '# Gamma\n\n## B only\n', { author: B, reason: 'rewrite' });
  assert.equal(res.ok, false);
  if (res.ok) return;
  assert.equal(res.lost[0].key, "## A's part");
  assert.ok(res.lost[0].owners.includes('session-a'));
  assert.match(res.message, /removes sections written by another session/);
  assert.equal(fs.readFileSync(path.join(root.dir, GAMMA), 'utf8'), WITH_A);
});

test('a session can add its own section and remove its own section', async () => {
  const root = await adopted();
  await writeNote(root, GAMMA, WITH_A, { author: A, reason: 'create' });
  const add = await editNote(root, GAMMA, { old: 'written by A\n', new: "written by A\n\n## B's part\n\nby B\n" }, { author: B, reason: 'add B' });
  assert.equal(add.ok, true);
  const remove = await editNote(root, GAMMA, { old: "\n## B's part\n\nby B\n", new: '' }, { author: B, reason: 'drop B' });
  assert.equal(remove.ok, true);
  assert.equal(fs.readFileSync(path.join(root.dir, GAMMA), 'utf8'), WITH_A);
});

test('a lease lets a session through the guard, and the entry records it', async () => {
  const root = await adopted();
  await writeNote(root, GAMMA, WITH_A, { author: A, reason: 'create' });
  grantLease(root, { session: 'session-b', rel: GAMMA, minutes: 10, reason: 'a human confirmed' });
  const res = await writeNote(root, GAMMA, '# Gamma\n', { author: B, reason: 'cleanup' });
  assert.equal(res.ok, true);
  if (res.ok) assert.ok(res.entry.override?.lease);
});

test('an external write is detected on the next access and names what it removed', async () => {
  const root = await adopted();
  const first = await writeNote(root, GAMMA, WITH_A, { author: A, reason: 'create' });
  assert.ok(first.ok);
  fs.writeFileSync(path.join(root.dir, GAMMA), '# Gamma\n');
  const read = await readNote(root, GAMMA);
  assert.equal(read.content, '# Gamma\n');
  const ext = lastEntry(root);
  assert.equal(ext?.op, 'external');
  assert.equal(ext?.author.agent, 'external');
  assert.equal(ext?.before, sha256(WITH_A));
  assert.equal(ext?.after, sha256('# Gamma\n'));
  assert.ok(ext?.violations?.includes("## A's part"));
});

test('history, show, as-of and restore', async () => {
  const root = await adopted();
  const v1 = WITH_A;
  const v2 = WITH_A.replace('written by A', 'rewritten by A');
  await writeNote(root, GAMMA, v1, { author: A, reason: 'v1' });
  await sleep(30);
  const between = new Date();
  await sleep(30);
  await editNote(root, GAMMA, { old: 'written by A', new: 'rewritten by A' }, { author: A, reason: 'v2' });
  const h = history(root, GAMMA, { limit: 10 });
  assert.deepEqual(h.slice(0, 2).map((e) => e.reason), ['v2', 'v1']);
  assert.equal(asOf(root, GAMMA, between)?.content, v1);
  const back = await restore(root, GAMMA, h[1].id, { author: A, reason: 'undo v2' });
  assert.equal(back.ok, true);
  if (back.ok) assert.equal(back.entry.op, 'restore');
  assert.equal(fs.readFileSync(path.join(root.dir, GAMMA), 'utf8'), v1);
  assert.equal(fs.readFileSync(path.join(root.dir, GAMMA), 'utf8'), showVersion(root, sha256(v1)));
  assert.notEqual(v2, v1);
});

test('two-phase writes (hooks) record the tool write without an external entry', async () => {
  const root = await adopted();
  await writeNote(root, GAMMA, WITH_A, { author: A, reason: 'create' });
  const after = `${WITH_A}\n## A's second part\n`;
  const prep = await prepareWrite(root, GAMMA, after, { author: A, tool: 'Edit', key: 'tool-use-1' });
  assert.equal(prep.ok, true);
  fs.writeFileSync(path.join(root.dir, GAMMA), after); // what the native tool does
  const done = await commitWrite(root, 'tool-use-1');
  assert.equal(done.ok, true);
  const tail = readLedger(root).entries.filter((e) => e.rel === GAMMA);
  assert.ok(!tail.some((e) => e.op === 'external'), 'the tool write is not external');
  assert.equal(tail.at(-1)?.after, sha256(after));
  assert.equal(tail.at(-1)?.author.session, 'session-a');

  const denied = await prepareWrite(root, GAMMA, '# Gamma\n', { author: B, tool: 'Write', key: 'tool-use-2' });
  assert.equal(denied.ok, false);
});

test('moving a note rewrites the links that point to it and keeps its history', async () => {
  const root = await adopted();
  const res = await moveNote(root, 'projects/alpha.md', 'archive/alpha-2025.md', { author: A, reason: 'archive' });
  assert.ok(res.linksRewritten >= 2);
  const links = fs.readFileSync(path.join(root.dir, 'notes/links.md'), 'utf8');
  assert.match(links, /\[\[alpha-2025\]\]/);
  assert.match(links, /\[\[alpha-2025#Plan\|the plan\]\]/);
  assert.ok(!fs.existsSync(path.join(root.dir, 'projects/alpha.md')));
  const h = history(root, 'archive/alpha-2025.md', { limit: 10 });
  assert.ok(h.some((e) => e.op === 'adopt'), 'history follows the move');
});

test('paths outside the root or inside the state directory are refused', async () => {
  const root = await adopted();
  await assert.rejects(writeNote(root, '../outside.md', 'x', { author: A, reason: 'x' }), { code: 'PATH_ESCAPES_ROOT' });
  await assert.rejects(writeNote(root, '.mneme/ledger.jsonl', 'x', { author: A, reason: 'x' }), { code: 'PATH_IN_STATE_DIR' });
});

/**
 * Runs `n` writer processes released together.
 * @param {string} dir @param {string} rel @param {number} n @param {string} mode @param {NodeJS.ProcessEnv} env
 */
async function runWriters(dir, rel, n, mode, env) {
  const go = path.join(dir, `go-${Date.now()}`);
  const children = Array.from({ length: n }, (_, i) =>
    new Promise((resolve) => {
      const child = spawn(process.execPath, [WRITER, dir, rel, String(i), go, mode], { env: { ...process.env, ...env } });
      child.on('exit', (code) => resolve(code));
    }),
  );
  await sleep(1500);
  fs.writeFileSync(go, '');
  return Promise.all(children);
}

test('TE-2: ten concurrent writers lose nothing with the lock, and the harness detects loss without it', async () => {
  const root = await adopted();
  const rel = 'notes/shared.md';
  await writeNote(root, rel, '# Shared\n\n<!-- end -->\n', { author: A, reason: 'create' });
  const codes = await runWriters(root.dir, rel, 10, 'append', {});
  // A writer that failed (a lock timeout, say) also leaves its section out: the codes tell
  // "did not write" apart from "wrote and was lost", which the count alone cannot (25/09).
  assert.deepEqual(codes, new Array(10).fill(0), 'every writer finished its write');
  const locked = fs.readFileSync(path.join(root.dir, rel), 'utf8');
  const survived = [...locked.matchAll(/^## Writer \d+$/gm)].length;
  assert.equal(survived, 10, 'with the lock every writer survives');
  assert.equal(readLedger(root).corrupt, 0);
  const errors = path.join(root.stateDir, 'run', 'errors.jsonl');
  const recorded = fs.existsSync(errors) ? fs.readFileSync(errors, 'utf8') : '';
  assert.doesNotMatch(recorded, /taken by mistake|taken over/, 'no two writers ever held the lock at once');

  // Negative control: without the lock AND without the check before the rename, the harness
  // must see a loss, or this test could not see one either.
  const control = await adopted();
  await writeNote(control, rel, '# Shared\n\n<!-- end -->\n', { author: A, reason: 'create' });
  await runWriters(control.dir, rel, 10, 'append', { MNEME_UNSAFE_NO_LOCK: '1', MNEME_UNSAFE_NO_CAS: '1', MNEME_TEST_RACE_DELAY_MS: '200' });
  const unlocked = fs.readFileSync(path.join(control.dir, rel), 'utf8');
  const kept = [...unlocked.matchAll(/^## Writer \d+$/gm)].length;
  assert.ok(kept < 10, `without the lock the harness must see a loss (kept ${kept}/10)`);
});

test('a write does not overwrite a note that changed after it was read under the lock (NOTE_CHANGED)', async () => {
  const root = await adopted();
  const rel = 'notes/shared.md';
  await writeNote(root, rel, '# Shared\n\n<!-- end -->\n', { author: A, reason: 'create' });
  process.env.MNEME_TEST_RACE_DELAY_MS = '150';
  try {
    const edit = editNote(root, rel, { old: '<!-- end -->', new: '## A\n\n<!-- end -->' }, { author: A, reason: 'race' });
    await sleep(50);
    // someone the lock did not stop (a second holder, an editor) writes in between
    fs.appendFileSync(path.join(root.dir, rel), 'written by someone else\n');
    await assert.rejects(edit, { code: 'NOTE_CHANGED' });
  } finally {
    delete process.env.MNEME_TEST_RACE_DELAY_MS;
  }
  assert.match(fs.readFileSync(path.join(root.dir, rel), 'utf8'), /written by someone else/, 'the other write survives');
  const { content } = await readNote(root, rel);
  assert.match(content, /written by someone else/);
  assert.equal(lastEntry(root)?.op, 'external', 'the next access records it, as for any write outside the tools');
});

test('TE-3: a crash before the rename leaves the old note intact and the ledger parseable', async () => {
  const root = await adopted();
  const rel = 'manuals/deploy.md';
  const original = fs.readFileSync(path.join(root.dir, rel), 'utf8');
  const [code] = await runWriters(root.dir, rel, 1, 'rewrite', { MNEME_TEST_CRASH_AT: 'before-rename' });
  assert.equal(code, 137);
  assert.equal(fs.readFileSync(path.join(root.dir, rel), 'utf8'), original);
  const { entries, corrupt } = readLedger(root);
  assert.equal(corrupt, 0);
  assert.ok(!entries.some((e) => e.rel === rel && e.op !== 'adopt'));
  await readNote(root, rel);
  assert.ok(!readLedger(root).entries.some((e) => e.rel === rel && e.op === 'external'), 'a leftover temp file is not an external write');
});

test('TE-3: a crash after the rename but before the ledger is caught as external on the next access', async () => {
  const root = await adopted();
  const rel = 'manuals/backups.md';
  const [code] = await runWriters(root.dir, rel, 1, 'rewrite', { MNEME_TEST_CRASH_AT: 'before-ledger' });
  assert.equal(code, 137);
  await readNote(root, rel);
  assert.equal(readLedger(root).entries.filter((e) => e.rel === rel).at(-1)?.op, 'external');
});

// ── Findings of the contract review (rebote 24/09), R-1..R-4 ────────────────

test('R-1: with repeated titles the guard cannot tell which copy went, so it denies', async () => {
  const root = await adopted();
  await writeNote(root, GAMMA, '# Gamma\n\n## Config\n\nby A\n', { author: A, reason: 'A config' });
  const b = await editNote(root, GAMMA, { old: 'by A\n', new: 'by A\n\n## Config\n\nby B\n' }, { author: B, reason: 'B config' });
  assert.equal(b.ok, true);
  // A removes B's copy and keeps its own: the count goes 2 -> 1, which the old rule allowed.
  const res = await editNote(root, GAMMA, { old: '\n## Config\n\nby B\n', new: '' }, { author: A, reason: 'drop the other one' });
  assert.equal(res.ok, false);
  assert.match(fs.readFileSync(path.join(root.dir, GAMMA), 'utf8'), /by B/);
});

test('R-2: a raced two-phase write attributes only what its author intended', async () => {
  const root = await adopted();
  const base = '# Gamma\n\n<!-- end -->\n';
  await writeNote(root, GAMMA, base, { author: A, reason: 'create' });
  const intended = base.replace('<!-- end -->', "## A's part\n\n<!-- end -->");
  const prep = await prepareWrite(root, GAMMA, intended, { author: A, tool: 'Edit', key: 'race-a' });
  assert.equal(prep.ok, true);
  // B writes between A's two phases.
  await editNote(root, GAMMA, { old: '<!-- end -->', new: "## B's part\n\n<!-- end -->" }, { author: B, reason: 'B in the middle' });
  // A's native tool applies its edit on the current file, which now has B's part too.
  const current = fs.readFileSync(path.join(root.dir, GAMMA), 'utf8');
  fs.writeFileSync(path.join(root.dir, GAMMA), current.replace('<!-- end -->', "## A's part\n\n<!-- end -->"));
  const done = await commitWrite(root, 'race-a');
  assert.equal(done.ok, true);
  if (!done.ok) return;
  assert.equal(done.entry.raced, true);
  assert.equal(done.entry.delta["## A's part"], 1);
  assert.equal(done.entry.delta["## B's part"], undefined, "B's part is not attributed to A");
  // Ownership stayed right: B can still remove its own section.
  const drop = await editNote(root, GAMMA, { old: "## B's part\n\n", new: '' }, { author: B, reason: 'B drops its own' });
  assert.equal(drop.ok, true);
});

test('R-3: a two-phase write whose commit never ran is confirmed late, as its author, not as external', async () => {
  const root = await adopted();
  await writeNote(root, GAMMA, WITH_A, { author: A, reason: 'create' });
  const after = `${WITH_A}\n## A again\n`;
  const prep = await prepareWrite(root, GAMMA, after, { author: A, tool: 'Edit', key: 'orphan-1' });
  assert.equal(prep.ok, true);
  fs.writeFileSync(path.join(root.dir, GAMMA), after); // the tool ran; the commit hook never did
  await readNote(root, GAMMA);
  const last = readLedger(root).entries.filter((e) => e.rel === GAMMA).at(-1);
  assert.equal(last?.author.session, 'session-a');
  assert.equal(last?.late, true);
  assert.notEqual(last?.op, 'external');
});

test('R-4: the ledger chain exposes a line edited in the middle', async () => {
  const root = await adopted();
  await writeNote(root, GAMMA, WITH_A, { author: A, reason: 'first' });
  await editNote(root, GAMMA, { old: 'written by A', new: 'written again by A' }, { author: A, reason: 'second' });
  assert.equal(readLedger(root).broken, 0);
  const file = path.join(root.stateDir, 'ledger.jsonl');
  const lines = fs.readFileSync(file, 'utf8').split('\n');
  const i = lines.findIndex((l) => l.includes('"reason":"first"'));
  lines[i] = lines[i].replace('"reason":"first"', '"reason":"tampered"');
  fs.writeFileSync(file, lines.join('\n'));
  const after = readLedger(root);
  assert.equal(after.corrupt, 0, 'the line is still valid JSON');
  assert.ok(after.broken >= 1, 'but the chain shows it was edited');
});
